properties.query:
let container_events = KubeAuditLogs | where OperationName has_any ("exec", "attach", "port-forward") and StatusCode == "Success" | summarize container_time=min(TimeGenerated) by User, Namespace;
let metadata_events = NetworkEvents | where DestinationIP in ("169.254.169.254", "fd00:ec2::254") | summarize metadata_time=min(TimeGenerated) by SourceIP;
let iam_events = AzureActivity | where OperationNameValue has_any ("Microsoft.Authorization/roleAssignments/write", "Microsoft.Authorization/roleDefinitions/write") | summarize iam_time=min(TimeGenerated) by Caller;
container_events | join kind=inner metadata_events on $left.User == $right.SourceIP | where metadata_time - container_time between (0min .. 60min)
